export function requestThenRead() {
  const request =
    Deno.permissions.requestSync({ name: "env", variable: "DEPUTY" }).state;
  try {
    return { request, read: Deno.env.get("DEPUTY") };
  } catch (error) {
    return { request, read: error.name };
  }
}

export function directRead() {
  return Deno.env.get("DEPUTY");
}
